#include <bits/stdc++.h>
using namespace std;

#define N (int)3e+5

vector<int>e[N];
bool vis[N];
bool can[N];
int cvis,ccan;

void dfs(int k,int mx){
	vis[k]=true;
	cvis++;
	int sz=e[k].size();
	for(int i=0;i<sz;i++){
		if((!vis[e[k][i]])&&(e[k][i]<=mx))dfs(e[k][i],mx);
		if(!can[e[k][i]]){
			can[e[k][i]]=true;
			ccan++;
		}
	}
	return;
}

int main(void){
	int n,m,x,y;
	cin>>n>>m;
	for(int i=0;i<m;i++){
		cin>>x>>y;
		e[x-1].push_back(y-1);
	}

	for(int i=0;i<n;i++){
		vis[i]=false,can[i]=false;
	}
	cvis=0,ccan=0;

	for(int i=0;i<n;i++){
		if(i==0){
			can[0]=true;
			ccan++;
		}
		if(can[i])dfs(i,i);
		if(cvis==(i+1))cout<<(ccan-cvis)<<endl;
		else cout<<-1<<endl;
	}

	return 0;
}
